use rbn_core::{engine::Engine,models,storage,report::Report};
use serde_json::{json,Value};
use std::{fs,path::PathBuf,sync::Arc,time::{Duration,Instant},thread};
struct Fixture{root:PathBuf,engine:Arc<Engine>}
impl Fixture{
 fn new()->Self{let root=std::env::temp_dir().join(format!("rbn-rust-test-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let engine=Engine::new(root.join("state"),root.join("tools")).unwrap();let binary=std::env::var("RBN_TEST_RCLONE").expect("Set RBN_TEST_RCLONE to run the required real-rclone integration suite");let config=root.join("rclone.conf");fs::write(&config,"").unwrap();engine.invoke("saveSettings",vec![json!({"rclonePath":binary,"configPath":config.to_string_lossy(),"language":"zh-TW"})]).unwrap();Self{root,engine}}
 fn request(&self,mode:&str)->Value{let from=self.root.join("source");let to=self.root.join("destination");fs::create_dir_all(&from).unwrap();fs::create_dir_all(&to).unwrap();json!({"source":{"remote":null,"path":from},"destination":{"remote":null,"path":to},"mode":mode,"options":models::default_options(),"selection":[],"dryRun":false})}
 fn run(&self,request:Value)->Value{let job=self.engine.invoke("startTransfer",vec![request]).unwrap();let id=job["id"].as_str().unwrap();let until=Instant::now()+Duration::from_secs(30);loop{let jobs=self.engine.invoke("listJobs",vec![]).unwrap();let job=jobs.as_array().unwrap().iter().find(|j|j["id"]==id).unwrap().clone();if ["completed","failed","cancelled"].contains(&job["status"].as_str().unwrap_or("")){return job;}assert!(Instant::now()<until,"job did not finish: {job}");thread::sleep(Duration::from_millis(20));}}
 #[cfg(unix)]fn wrapper(&self,script:&str){use std::os::unix::fs::PermissionsExt;let path=self.root.join("test-rclone");let real=std::env::var("RBN_TEST_RCLONE").unwrap();let quote=|s:&str|format!("'{}'",s.replace('\'',"'\\''"));let content=format!("#!/bin/sh\nREAL={}\nMARKER={}\nTRACE={}\n{}\n",quote(&real),quote(&self.root.join("first-pass").to_string_lossy()),quote(&self.root.join("passes").to_string_lossy()),script);fs::write(&path,content).unwrap();fs::set_permissions(&path,fs::Permissions::from_mode(0o700)).unwrap();self.engine.invoke("saveSettings",vec![json!({"rclonePath":path})]).unwrap();}
}
impl Drop for Fixture{fn drop(&mut self){let _=self.engine.invoke("_shutdown",vec![]);let _=fs::remove_dir_all(&self.root);}}
#[test]fn real_copy_move_and_report(){let f=Fixture::new();let request=f.request("copy");fs::write(f.root.join("source/測試🤍.txt"),b"content").unwrap();let job=f.run(request);assert_eq!(job["status"],"completed","{job}");assert_eq!(fs::read(f.root.join("destination/測試🤍.txt")).unwrap(),b"content");let report=f.engine.invoke("getJobReport",vec![job["id"].clone(),json!({"category":"success"})]).unwrap();assert!(report["items"].as_array().unwrap().iter().any(|i|i["action"]=="copy"));let request=f.request("move");fs::write(f.root.join("source/moved.txt"),b"moved").unwrap();let job=f.run(request);assert_eq!(job["status"],"completed","{job}");assert!(!f.root.join("source/moved.txt").exists());assert_eq!(fs::read(f.root.join("destination/moved.txt")).unwrap(),b"moved");}
#[test]fn sync_removes_extra_files_and_directories(){let f=Fixture::new();let request=f.request("sync");fs::create_dir_all(f.root.join("source/present-empty")).unwrap();fs::create_dir_all(f.root.join("destination/extra/nested")).unwrap();fs::write(f.root.join("destination/obsolete.txt"),b"old").unwrap();fs::write(f.root.join("source/current.txt"),b"new").unwrap();let job=f.run(request);assert_eq!(job["status"],"completed","{job}");assert!(!f.root.join("destination/extra").exists());assert!(!f.root.join("destination/obsolete.txt").exists());assert!(f.root.join("destination/present-empty").is_dir());}
#[test]fn dry_run_never_changes_files_or_directories(){let f=Fixture::new();let mut request=f.request("sync");request["dryRun"]=json!(true);fs::create_dir_all(f.root.join("destination/extra")).unwrap();fs::write(f.root.join("destination/old"),b"old").unwrap();fs::write(f.root.join("source/new"),b"new").unwrap();let job=f.run(request);assert_eq!(job["status"],"completed","{job}");assert!(f.root.join("destination/extra").is_dir());assert_eq!(fs::read(f.root.join("destination/old")).unwrap(),b"old");assert!(!f.root.join("destination/new").exists());}
#[test]fn selected_sync_with_include_preserves_unselected_and_excluded(){let f=Fixture::new();let mut request=f.request("sync");request["selection"]=json!([{"name":"selected","isDir":true}]);request["options"]["include"]=json!(["*.txt"]);for path in ["source/selected","destination/selected","destination/unselected"]{fs::create_dir_all(f.root.join(path)).unwrap();}fs::write(f.root.join("source/selected/new.txt"),b"new").unwrap();for path in ["destination/selected/stale.txt","destination/selected/protected.jpg","destination/unselected/keep.txt"]{fs::write(f.root.join(path),b"keep").unwrap();}let job=f.run(request);assert_eq!(job["status"],"completed","{job}");assert!(!f.root.join("destination/selected/stale.txt").exists());assert!(f.root.join("destination/selected/protected.jpg").exists());assert!(f.root.join("destination/unselected/keep.txt").exists());assert!(f.root.join("destination/selected/new.txt").exists());}
#[test]#[cfg(unix)]fn permanent_source_error_still_prunes_only_safe_empty_orphans(){let f=Fixture::new();let request=f.request("sync");for p in ["source/present","destination/present","destination/extra-empty","destination/extra-populated"]{fs::create_dir_all(f.root.join(p)).unwrap();}fs::write(f.root.join("destination/extra-populated/protect"),b"keep").unwrap();f.wrapper("for a do case \"$a\" in sync) printf '%s\\n' '{\"level\":\"error\",\"object\":\"present\",\"objectType\":\"*local.Directory\",\"msg\":\"error reading source directory: permission denied\"}' >&2; exit 1;; esac; done\nexec \"$REAL\" \"$@\"");let job=f.run(request.clone());assert_eq!(job["status"],"failed");assert!(!f.root.join("destination/extra-empty").exists());assert!(f.root.join("destination/present").exists());assert_eq!(fs::read(f.root.join("destination/extra-populated/protect")).unwrap(),b"keep");assert_eq!(job["stats"]["deletes"].as_f64(),Some(0.0),"directory cleanup must not change the rclone file-delete counter");let report=f.engine.invoke("getJobReport",vec![job["id"].clone(),json!({"category":"success"})]).unwrap();assert_eq!(report["summary"]["directoryDeletedEvents"],json!(1));assert!(job["logs"].as_array().unwrap().iter().any(|l|l["message"]=="已清理 1 個來源不存在的空資料夾。"));let second=f.run(request);assert_eq!(second["status"],"failed");assert_eq!(second["stats"]["deletes"].as_f64(),Some(0.0));let report=f.engine.invoke("getJobReport",vec![second["id"].clone(),json!({"category":"success"})]).unwrap();assert_eq!(report["summary"]["directoryDeletedEvents"],json!(0));assert!(second["logs"].as_array().unwrap().iter().any(|l|l["message"]=="已清理 0 個來源不存在的空資料夾。"));assert_eq!(fs::read(f.root.join("destination/extra-populated/protect")).unwrap(),b"keep");}
#[test]#[cfg(unix)]fn temporary_error_retries_only_failed_file(){let f=Fixture::new();let mut request=f.request("copy");request["options"]["exclude"]=json!(["*.tmp"]);fs::write(f.root.join("source/x.txt"),b"x").unwrap();fs::write(f.root.join("source/y.txt"),b"y").unwrap();fs::write(f.root.join("source/excluded.tmp"),b"no").unwrap();f.wrapper("transfer=0; for a do case \"$a\" in copy) transfer=1;; esac; done\nif [ \"$transfer\" = 1 ]; then printf '%s\\n' \"$*\" >> \"$TRACE\"; \"$REAL\" \"$@\"; result=$?; if [ ! -e \"$MARKER\" ]; then : > \"$MARKER\"; printf '%s\\n' '{\"level\":\"error\",\"object\":\"x.txt\",\"objectType\":\"*local.Object\",\"msg\":\"network timeout\"}' >&2; exit 1; fi; exit $result; fi\nexec \"$REAL\" \"$@\"");let job=f.run(request);assert_eq!(job["status"],"completed","{job}");let trace=fs::read_to_string(f.root.join("passes")).unwrap();let lines=trace.lines().collect::<Vec<_>>();assert_eq!(lines.len(),2,"{trace}");assert!(lines[1].contains("--files-from-raw="));assert!(!lines[1].contains("--filter-from="));assert!(!f.root.join("destination/excluded.tmp").exists());}
#[test]fn rejects_dangerous_selected_delete_excluded_before_mutation(){let f=Fixture::new();let mut request=f.request("sync");request["selection"]=json!([{"name":"selected","isDir":true}]);request["options"]["deleteExcluded"]=json!(true);assert!(f.engine.invoke("startTransfer",vec![request]).is_err());assert!(f.engine.invoke("listJobs",vec![]).unwrap().as_array().unwrap().is_empty());}
#[test]fn failed_settings_patch_preserves_previous_revision(){let f=Fixture::new();let before=f.engine.invoke("_preferences",vec![]).unwrap();assert!(f.engine.invoke("saveSettings",vec![json!({"maxConcurrentJobs":true})]).is_err());let after=f.engine.invoke("_preferences",vec![]).unwrap();assert_eq!(before,after);}
#[test]fn interrupted_history_is_not_automatically_restarted(){let f=Fixture::new();let request=f.request("copy");let id=uuid::Uuid::new_v4().to_string();let state=f.root.join("other-state");fs::create_dir_all(&state).unwrap();storage::atomic_json(&state.join("jobs.json"),&json!([{"id":id,"request":request,"status":"running","createdAt":"2026-11-27T01:00:00Z","stats":{},"logs":[],"command":"rclone"}])).unwrap();let engine=Engine::new(state,f.root.join("other-tools")).unwrap();let jobs=engine.invoke("listJobs",vec![]).unwrap();assert_eq!(jobs[0]["status"],"interrupted");assert!(!f.root.join("destination/new").exists());engine.invoke("_shutdown",vec![]).unwrap();}
#[test]fn report_pagination_preserves_category_and_unicode(){let root=std::env::temp_dir().join(format!("rbn-report-test-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let id=uuid::Uuid::new_v4().to_string();let mut r=Report::new(&root,&id).unwrap();for n in 0..12{r.consume(&json!({"level":"info","object":format!("{n}-測試🤍.txt"),"msg":"Copied (new)","size":1}),false).unwrap();r.comparison_line(&format!("= {n}.txt"),true).unwrap();}r.finish().unwrap();let mut cursor=json!(0);let mut collected=vec![];loop{let q=json!({"category":"success","limit":3,"cursor":cursor});let page=rbn_core::report::page(&root,&id,&q,r.summary()).unwrap();collected.extend(page["items"].as_array().unwrap().clone());cursor=page["nextCursor"].clone();if cursor.is_null(){break;}}assert_eq!(collected.len(),12);assert!(collected.iter().all(|i|i["status"]=="success"));drop(r);fs::remove_dir_all(root).unwrap();}
